// AWI: SEO TiTAN 7 DM - sekali jalan (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/titanseo', array(
		'methods' => array('GET', 'POST'),
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function ($req) {
			global $wpdb;
			$out = array();
			foreach (array(10706, 10818) as $id) {
				$c = $wpdb->get_var($wpdb->prepare("SELECT post_content FROM {$wpdb->posts} WHERE ID=%d", $id));
				$i = stripos($c, 'TiTAN 7 DM');
				$f = false;
				foreach (array('FAQ BYD TiTAN', 'Pertanyaan yang sering') as $k) { $f = stripos($c, $k); if ($f !== false) break; }
				$out[$id] = array(
					'len' => strlen($c),
					'first_h2' => substr($c, max(0, stripos($c, '<h2') - 200), 900),
					'faq' => $f === false ? null : substr($c, max(0, $f - 300), 1800),
				);
			}
			return $out;
		},
	));
});
